package com.example.assets_management.security.service;
import io.jsonwebtoken.*; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.GrantedAuthority; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class JwtService { private final SecretKey jwtSigningKey; @Value("${JWT_EXPIRATION_MS:900000}") private long expirationMs;
 public String generateToken(UserDetails d){Instant n=Instant.now(),e=n.plusMillis(expirationMs); var b=Jwts.builder().subject(d.getUsername()).id(UUID.randomUUID().toString()).issuedAt(Date.from(n)).expiration(Date.from(e)); if(d instanceof CustomUserDetails c){if(c.getUserId()!=null)b.claim("userId",c.getUserId().toString());if(c.getCompanyId()!=null)b.claim("companyId",c.getCompanyId().toString());if(c.getBranchId()!=null)b.claim("branchId",c.getBranchId().toString());if(c.getDepartmentId()!=null)b.claim("departmentId",c.getDepartmentId().toString());if(c.getRoleId()!=null)b.claim("roleId",c.getRoleId().toString());if(c.getRoleName()!=null)b.claim("role",c.getRoleName());} b.claim("permissions",d.getAuthorities().stream().map(GrantedAuthority::getAuthority).filter(x->!x.startsWith("ROLE_")).distinct().toList()); return b.signWith(jwtSigningKey).compact(); }
 public String extractUsername(String t){return claims(t).getSubject();} public UUID extractUserId(String t){return uuid(claims(t).get("userId"));} public String extractJti(String t){return claims(t).getId();} public UUID extractCompanyId(String t){return uuid(claims(t).get("companyId"));} public boolean isTokenValid(String t,UserDetails d){try{Claims c=claims(t);return d.isEnabled()&&d.getUsername().equals(c.getSubject())&&c.getExpiration()!=null&&c.getExpiration().after(new Date())&&(d instanceof CustomUserDetails cu&&Objects.equals(cu.getUserId(),extractUserId(t)));}catch(JwtException|IllegalArgumentException e){return false;}} public long getExpirationMs(){return expirationMs;} private Claims claims(String t){return Jwts.parser().verifyWith(jwtSigningKey).build().parseSignedClaims(t).getPayload();} private UUID uuid(Object v){return v==null?null:UUID.fromString(v.toString());} }
